long long countArrangements(int n, int pos, vector<char>& used) {
    if (pos == 0) return 1;
    long long total = 0;
    for (int v = 1; v <= n; v++) {
        if (!used[v] && (v % pos == 0 || pos % v == 0)) {
            used[v] = 1;
            total += countArrangements(n, pos - 1, used);
            used[v] = 0;
        }
    }
    return total;
}

int main() {
    long long n;
    cin >> n;

    vector<char> used(n + 1, 0);
    cout << countArrangements((int)n, (int)n, used) << "\n";

    return 0;
}

