import java.util.*;

public class Main {
    static long countArrangements(int n, int pos, boolean[] used) {
        if (pos == 0) return 1;
        long total = 0;
        for (int v = 1; v <= n; v++) {
            if (!used[v] && (v % pos == 0 || pos % v == 0)) {
                used[v] = true;
                total += countArrangements(n, pos - 1, used);
                used[v] = false;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        System.out.println(countArrangements((int) n, (int) n, new boolean[(int) n + 1]));
    }
}
